#!/usr/bin/env bash
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../../../core" && pwd -P)}/hooks/lib/role-directive.sh"
YOU_DECIDE=$'YOU DECIDE: nothing about screens, flows, heuristics, or accessibility —\nthis plugin owns exactly one cross-cutting constraint: that the\ninteraction-design methodology'"'"'s stages happen in order (survey ->\nscout -> proposal -> [human approval] -> phase-2 record). It composes\ninto BOTH the phase-1 proposal norm and the phase-2 judgment norm per\ndocs/issue-21/proposals/issue-21-interaction-design-gate-machine.md §4,\nalongside every other id-* plugin, none of which it depends on or is\ndepended on by in code — only through the shared on-disk\n.status.json contract.'
USE_WHEN=$'USE WHEN: any Write/Edit/MultiEdit that would CREATE\ndocs/issue-<n>/proposals/*.md (not an edit to an already-existing\nproposal file), or any Write/Edit/MultiEdit to\ndocs/issue-<n>/reports/interaction-design.md (the phase-2 record). Every\nother write path is not this plugin'"'"'s business.'
PRODUCES=$'PRODUCES: a purely local, offline ordering check — file EXISTENCE only,\nnever content, and never a GitHub/network call. Before a new proposal\nfile: both docs/issue-<n>/reports/interaction-design/survey.md and\nscout-brief.md must already exist on disk, UNLESS the survey itself\nrecords an explicit scout-skip (a line matching /skip(ped)?/i near\n/scout/i), in which case scout-brief.md'"'"'s absence is excused. Before a\nrecord write: at least one docs/issue-<n>/proposals/*.md file must\nalready exist on disk. This plugin does NOT check GitHub or human\napproval itself -- core'"'"'s hooks/approval-gate.sh already fail-closed-\nblocks any execution-surface write (including this record file) until\nan allowlisted human'"'"'s Approve exists on GitHub. This plugin is a\nnarrower, purely-local ordering check layered ON TOP OF, never instead\nof, core'"'"'s approval-gate.'
HAND_OFF=$'HAND-OFF: on every passing write (not a skip-exit for an out-of-scope\npath), this plugin read-merges-writes\ndocs/issue-<n>/reports/interaction-design/.status.json -- a JSON object\nkeyed by "issue-<n>", each value an object with string fields survey,\nscout, proposal, record set to "done" once the corresponding\nartifact-presence check has passed for that subject. This file is\nrecomputed from actual file presence on every pass, never trusted from a\nprior value, and it is the shared on-disk contract the other ten\ninteraction-design plugins independently read/write their own keys\ninto (proposal_shape, persona_goal, etc.) -- no plugin-to-plugin code\ndependency, only this one shared file, merged (never clobbered) on every\nwrite.'
core_role_directive "$YOU_DECIDE" "$USE_WHEN" "$PRODUCES" "$HAND_OFF"
